    'Executor 관리, Task 배정, 결과 집계, 컨테이너 간 통신에 시간이 필요합니다. 같은 PC의 자원을 놓고 경쟁하면 8 Worker가 4 Worker보다 느리거나 비슷할 수 있습니다.':
      " Executor management, Task scheduling, result aggregation, and container communication take time. Competing for one PC's resources can make eight Workers slower than or similar to four.",
    '첫 실행의 영향:': ' First-run effects:',
