    '는 조건이 True인 행만 남깁니다. NULL은 0이나 빈 문자열과 같지 않으며, NULL과의 일반 비교는 알 수 없는 결과가 될 수 있습니다.':
      ' keeps only rows whose condition is True. NULL is neither zero nor an empty string; ordinary comparisons involving NULL may yield unknown.',
