    '원천 기록 가져오기': ' Retrieve source records',
    '규칙에 맞게 정리': ' Apply processing rules',
    '다시 쓸 수 있게 보관': ' Store for reuse',
    제공: ' Serving',
    '분석·서비스에 전달': ' Deliver to analysts and services',
    '① 수집: 주문 A001 10,000원, A002 20,000원, 재전송된 A002 20,000원을 받았어요. 아직 3행이라는 사실만 알 수 있습니다. 원본을 먼저 확보합니다.':
      ' ① Collect: Receive A001 for KRW 10,000, A002 for KRW 20,000, and a retransmission of A002 for KRW 20,000. So far, we only know there are three rows. Preserve the originals first.',
    '② 변환: “같은 주문 번호의 재전송은 한 번만 센다”는 명세를 적용해요. A002를 한 번만 반영하면 실제 주문은 2건, 합계는 30,000원입니다.':
      ' ② Transform: Apply the rule that a retransmission of the same order ID is counted once. Counting A002 once gives two actual orders totaling KRW 30,000.',
    '③ 저장: 원본 3행과 정리된 결과 2건을 구분해 보관해요. 규칙을 고치거나 오류를 찾았을 때 원본에서 다시 계산할 수 있습니다.':
      ' ③ Store: Keep the three original rows separately from the two cleaned orders. If rules change or errors are found, recalculate from the originals.',
    '④ 제공: 분석가나 서비스가 사용할 매출표를 전달해요. 숫자 30,000원뿐 아니라 어떤 규칙으로 만든 값인지도 설명할 수 있어야 합니다.':
      ' ④ Serve: Deliver the sales table to analysts or services. Explain not only the KRW 30,000 total but also the rules that produced it.',
