    '대기 · Driver 없음': ' Waiting · No Driver',
    '아직 앱 없음': ' No app yet',
    'Worker·자원 관리': ' Worker and resource management',
    '↑ 등록·자원 보고 ↑': ' ↑ Registration and resource report ↑',
    '제공 자원 1 core · 1 GiB': ' Available: 1 core · 1 GiB',
    'Executor 아직 없음': ' No Executor yet',
    '① 클러스터 준비: Worker 두 개가 Master에 자원을 알립니다. Client는 대기 중이고 Driver와 Executor는 아직 없습니다. 컨테이너는 네 개입니다.':
      ' ① Prepare cluster: Two Workers report resources to Master. Client waits; no Driver or Executors exist yet. There are four containers.',
    '② 앱 제출: Client 안에서 spark-submit을 실행하면 Driver가 시작됩니다. Master에 앱을 등록하고 Executor를 실행할 자원을 요청합니다.':
      ' ② Submit app: Running spark-submit inside Client starts Driver. It registers the app with Master and requests resources for Executors.',
    '③ 실행 자원 준비: Master가 Worker에 Executor 실행을 지시합니다. 각 Worker에서 시작한 Executor가 Client의 Driver에 연결합니다.':
      ' ③ Prepare execution resources: Master tells Workers to start Executors. Each Executor connects to Driver inside Client.',
    '④ 계산: Driver가 Task를 조정하고 Executor가 실제 계산을 수행합니다. 상태와 결과는 Driver와 Executor 사이에서 전달되며 Master를 경유할 필요가 없습니다.':
      ' ④ Compute: Driver coordinates Tasks and Executors perform computation. Status and results pass directly between Driver and Executors without needing to go through Master.',
    '어디에서 접속하는 주소일까요?': ' Where does this connection start?',
    'localhost의 의미': ' Meaning of localhost',
    'Windows 브라우저': ' Windows browser',
    '호스트 포트 전달 →': ' Host port forwarding →',
    'Worker 2 컨테이너': ' Worker 2 container',
    'Windows의 localhost는 내 PC입니다. compose.yaml의 127.0.0.1:8082:8081은 PC의 8082를 Worker 2 내부 8081로 연결해요. Worker 1도 자기 컨테이너에서 8081을 사용할 수 있습니다.':
      ' On Windows, localhost is your PC. The compose.yaml mapping 127.0.0.1:8082:8081 connects PC port 8082 to port 8081 inside Worker 2. Worker 1 can also use 8081 inside its own container.',
    '작은 조각으로 나눠서 더하기': ' Split into pieces and add',
    '1. 데이터 4조각': ' 1. Four data pieces',
    '2. 부분 합계': ' 2. Partial sums',
    '3. 결과 확인': ' 3. Check result',
    '25개 숫자': ' 25 numbers',
    '① 입력 만들기: range(1, 101, 1, 4)는 1부터 100까지 숫자를 4개 입력 partition으로 나눕니다. 101은 포함하지 않아요. 그림의 범위는 분할을 이해하기 위한 모형입니다.':
      ' ① Create input: range(1, 101, 1, 4) divides numbers 1 through 100 into four input partitions; 101 is excluded. The illustrated ranges are a model for understanding partitioning.',
    '② 부분 합계: 각 조각의 숫자를 더하면 325, 950, 1575, 2200입니다. 조각은 4개지만 이 실습의 전체 Executor core는 2개이므로 네 조각을 모두 동시에 처리한다는 뜻은 아닙니다.':
      ' ② Partial sums: The four pieces sum to 325, 950, 1575, and 2200. Four pieces with only two total Executor cores do not mean all four run simultaneously.',
    '③ 결과 모으기: 부분 합계를 더하면 5050입니다. 실제 Spark 집계에는 추가 처리 단계가 있을 수 있어요. 이 그림은 덧셈 원리 설명이며 Spark UI의 Task 실행 순서를 그대로 재현한 화면은 아닙니다.':
      ' ③ Combine results: Adding the partial sums gives 5050. Actual Spark aggregation may have additional stages. This diagram explains the arithmetic; it does not reproduce the exact Task order in Spark UI.',
