    'Master 컨테이너': ' Master container',
    '컨테이너에서는 서비스 이름 spark-master로 Master를 찾습니다. Docker DNS는 이름에 해당하는 IP를 알려주고, 실제 연결은 받은 주소로 직접 이루어집니다. DNS용 컨테이너를 추가하지 않습니다.':
      ' Inside containers, find Master by the service name spark-master. Docker DNS returns its IP; the connection then goes directly to that address. No separate DNS container is added.',
    '앱이 살아 있을 때 →': ' While the app is alive →',
    'Client 안의 Driver': ' Driver inside Client',
    'Driver UI는 앱을 제출한 뒤 사용할 수 있어요. 기본 120초의 관찰 시간이 끝나 APP_STOPPED가 출력되면 Driver가 종료되어 이 화면도 닫힙니다. Client 컨테이너가 켜져 있어도 UI가 항상 존재하는 것은 아닙니다.':
      ' Driver UI is available after submission. When the default 120-second observation period ends and APP_STOPPED appears, Driver stops and its UI closes. A running Client container does not mean the UI always exists.',
