    '계산 자원 대기': ' Resources waiting',
    'Worker 1개 중 최대 1개가 이 앱에 참여합니다. Worker와 Executor마다 1 Core인 이번 설정의 예입니다. 실제 배정 위치는 달라질 수 있으며, 최종 집계는 별도 단계입니다.':
      ' At most 1 of 1 Workers participates. This configuration uses one core per Worker and Executor. Actual placement can vary; final aggregation is a separate stage.',
    'Worker 2개 중 최대 2개가 이 앱에 참여합니다. Worker와 Executor마다 1 Core인 이번 설정의 예입니다. 실제 배정 위치는 달라질 수 있으며, 최종 집계는 별도 단계입니다.':
      ' At most 2 of 2 Workers participate. This configuration uses one core per Worker and Executor. Actual placement can vary; final aggregation is a separate stage.',
    'Worker 4개 중 최대 4개가 이 앱에 참여합니다. Worker와 Executor마다 1 Core인 이번 설정의 예입니다. 실제 배정 위치는 달라질 수 있으며, 최종 집계는 별도 단계입니다.':
      ' At most 4 of 4 Workers participate. This configuration uses one core per Worker and Executor. Actual placement can vary; final aggregation is a separate stage.',
    'Worker 8개 중 최대 8개가 이 앱에 참여합니다. Worker와 Executor마다 1 Core인 이번 설정의 예입니다. 실제 배정 위치는 달라질 수 있으며, 최종 집계는 별도 단계입니다.':
      ' At most 8 of 8 Workers participate. This configuration uses one core per Worker and Executor. Actual placement can vary; final aggregation is a separate stage.',
